import java.util.*;
import java.io.*;
import java.math.*;

public class E {
    private static final long MOD = 998244353L;
    private static final BigInteger MOD_BIG = BigInteger.valueOf(MOD);
    private static final long HALF = (MOD + 1) / 2L;

    public static void main(String[] args) throws Exception {
        BufferedReader infile = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(infile.readLine());

        long N = Long.parseLong(st.nextToken());
        long M = Long.parseLong(st.nextToken());
        long L = Long.parseLong(st.nextToken());
        long R = Long.parseLong(st.nextToken());

        long cells = N * M;
        BigInteger base = BigInteger.valueOf(R - L + 1);
        BigInteger exponent = BigInteger.valueOf(cells);

        long result = base.modPow(exponent, MOD_BIG).longValue();

        if ((cells % 2L) == 1L) {
            System.out.println(result);
        } else {
            if (((R - L) % 2L) == 0L) {
                result++;
            }
            result = (result * HALF) % MOD;
            System.out.println(result);
        }
    }
}
